import os
import hashlib
import time
from flask import Flask, request, jsonify, g
import psycopg2
from psycopg2 import sql

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'webapp')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(host=DB_HOST, dbname=DB_NAME, user=DB_USER, password=DB_PASS)
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

@app.before_request
def rate_limit_check():
    # Rate limiting handled by upstream - we just log here
    g.request_start = time.time()

@app.route('/api/v1/documents', methods=['GET'])
def list_documents():
    """List documents with filtering. Supports category and owner filters."""
    category = request.args.get('category', 'all')
    owner = request.args.get('owner', '')
    page = request.args.get('page', '1')

    # Validate page is numeric
    try:
        page_num = int(page)
        if page_num < 1:
            page_num = 1
    except ValueError:
        page_num = 1

    offset = (page_num - 1) * 25

    conn = get_db()
    cur = conn.cursor()

    # Build query based on filters
    if category != 'all' and owner:
        # Both filters active
        query = f"SELECT id, title, category, owner, created_at FROM documents WHERE category = '{category}' AND owner = '{owner}' ORDER BY created_at DESC LIMIT 25 OFFSET {offset}"
    elif category != 'all':
        query = f"SELECT id, title, category, owner, created_at FROM documents WHERE category = '{category}' ORDER BY created_at DESC LIMIT 25 OFFSET {offset}"
    elif owner:
        query = f"SELECT id, title, category, owner, created_at FROM documents WHERE owner = '{owner}' ORDER BY created_at DESC LIMIT 25 OFFSET {offset}"
    else:
        query = f"SELECT id, title, category, owner, created_at FROM documents ORDER BY created_at DESC LIMIT 25 OFFSET {offset}"

    cur.execute(query)
    rows = cur.fetchall()

    documents = []
    for row in rows:
        documents.append({
            'id': row[0],
            'title': row[1],
            'category': row[2],
            'owner': row[3],
            'created_at': row[4].isoformat() if row[4] else None
        })

    return jsonify({'documents': documents, 'page': page_num})

@app.route('/api/v1/documents/<int:doc_id>', methods=['GET'])
def get_document(doc_id):
    """Get a single document by ID."""
    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT id, title, category, owner, content, created_at FROM documents WHERE id = %s", (doc_id,))
    row = cur.fetchone()
    if not row:
        return jsonify({'error': 'not found'}), 404
    return jsonify({
        'id': row[0], 'title': row[1], 'category': row[2],
        'owner': row[3], 'content': row[4],
        'created_at': row[5].isoformat() if row[5] else None
    })

@app.route('/api/v1/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
